INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 16, 'theory', 'Quiz: views');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 16, 0, 'Does a view (VIEW) store data?', '["Yes, as a copy of the table", "No, only the query text, which runs on access", "Only the first 1000 rows", "Only if there is an index"]', 1, 'An ordinary view stores only the query definition; the data is always taken from the tables, so it is fresh.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 16, 1, 'How do you change a view in SQLite?', '["ALTER VIEW", "CREATE OR REPLACE VIEW", "DROP VIEW and CREATE VIEW again", "UPDATE VIEW"]', 2, 'SQLite has no ALTER VIEW or OR REPLACE: the view is dropped and created again, preferably in one transaction.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 16, 2, 'Can you insert rows through a view in SQLite?', '["Yes, always", "No: views are read-only; writing goes through INSTEAD OF triggers", "Only if there is no JOIN", "Only if there is an index"]', 1, 'SQLite views are read-only. For writing you create an INSTEAD OF trigger that intercepts the operation.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 16, 3, 'Why is a star in a view definition dangerous?', '["It is forbidden by the syntax", "It is expanded once at creation: new table columns won''t appear in it", "It slows queries down 10 times", "It selects only numeric columns"]', 1, 'The list of columns is fixed at creation. It is better to list the columns explicitly.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 16, 4, 'What happens to table indexes when you query a view?', '["They aren''t used", "They work: the query is expanded into a query to the tables", "Only unique ones are used", "Indexes must be created for the view"]', 1, 'SQLite inlines the view definition into the query; the indexes of the underlying tables are applied as usual.');
